import{describe,it,expect}from"vitest";import{RIVERS_DATA,calculateAccuracy,renderFactSheet}from"../../frontend/river-trace/script.js";describe("River Trace Challenge Logic",()=>{it("should contain complete dataset for 5 major rivers with waypoints",()=>{const e=Object.keys(RIVERS_DATA);expect(e).toEqual(["ganga","yamuna","godavari","krishna","brahmaputra"]),e.forEach(e=>{const t=RIVERS_DATA[e];expect(t).toHaveProperty("id"),expect(t).toHaveProperty("name"),expect(t).toHaveProperty("length"),expect(Array.isArray(t.statesCrossed)).toBe(!0),expect(Array.isArray(t.tributaries)).toBe(!0),expect(Array.isArray(t.actualWaypoints)).toBe(!0),expect(t.actualWaypoints.length).toBeGreaterThanOrEqual(5)})}),it("should return 100% accuracy for identical waypoints",()=>{const e=RIVERS_DATA.ganga,t=calculateAccuracy(e.actualWaypoints,e.actualWaypoints);expect(t).toBe(100)}),it("should return scaled accuracy for offset waypoints",()=>{const e=calculateAccuracy([{x:110,y:110},{x:210,y:210}],[{x:100,y:100},{x:200,y:200}]);expect(e).toBeGreaterThan(80),expect(e).toBeLessThan(100)}),it("should return 0% accuracy for missing or empty waypoints",()=>{expect(calculateAccuracy([],RIVERS_DATA.ganga.actualWaypoints)).toBe(0),expect(calculateAccuracy(null,null)).toBe(0)}),it("should render detailed river fact sheet on completion",()=>{const e=renderFactSheet(RIVERS_DATA.godavari,92);expect(e).toContain("Godavari"),expect(e).toContain("Dakshin Ganga"),expect(e).toContain("Tracing Accuracy: 92%"),expect(e).toContain("1,465 km")})});